def _extract_interpreter(b_module_data):
    """Return the interpreter and arguments from the module's first line."""
    b_first_line = b_module_data.split(b'\n', 1)[0]
    if not b_first_line.startswith(b'#!'):
        return None, []
    parts = shlex.split(to_native(b_first_line[2:].strip(), errors='surrogate_or_strict'))
    parts = [to_text(part, errors='surrogate_or_strict') for part in parts]
    return (parts[0], parts[1:]) if parts else (None, [])


